import json

with open('./data.json') as f:
    data = json.load(f)

count = 0
for log in data['logs']:
    if log.get('endpoint') == '/api/auth':
        if 'error' in log and log['error'] is not None:
            if log['error'].get('retryable') is True:
                count += 1

print(count)
